import { expect, test } from '@playwright/test';
import { readFileSync } from 'node:fs';
import { makePdf } from '../fixtures';

// Generated by scripts/make-image-fixtures.py; optional development fixtures.
for (const [name, filter, file] of [['JPEG', 'DCTDecode', 'jpeg.jpg'], ['JPEG2000', 'JPXDecode', 'jpeg2000.jp2']]) {
  test(`Poppler decodes real ${name} image pixels`, async ({ page }) => {
    let bytes: Buffer;
    try { bytes = readFileSync(`.build/test-images/${file}`); }
    catch { test.skip(true, 'Run python3 scripts/make-image-fixtures.py to generate codec fixtures.'); return; }
    await page.goto('/viewer.html');
    await page.locator('#file-input').setInputFiles({ name: 'codec.pdf', mimeType: 'application/pdf', buffer: makePdf(1, { image: { bytes, filter, width: 128, height: 128 } }) });
    await expect(page.locator('.pdf-page.rendered')).toBeVisible();
    const pixel = await page.locator('.pdf-page canvas').evaluate((canvas: HTMLCanvasElement) => {
      const x = Math.round(180 / 612 * canvas.width), y = Math.round((792 - 600) / 792 * canvas.height);
      return Array.from(canvas.getContext('2d')!.getImageData(x, y, 1, 1).data);
    });
    expect(pixel[0]).toBeGreaterThan(180); expect(pixel[1]).toBeLessThan(80); expect(pixel[2]).toBeLessThan(80);
  });
}
